#include <bits/stdc++.h>
using namespace std;

vector<long long> subset_sums(const vector<long long>& a) {
    vector<long long> sums;
    sums.reserve(size_t{1} << a.size());
    sums.push_back(0);
    for (long long value : a) {
        size_t old_size = sums.size();
        for (size_t i = 0; i < old_size; ++i) {
            sums.push_back(sums[i] + value);
        }
    }
    return sums;
}

long long count_subsets(const vector<long long>& a, long long target) {
    size_t mid = a.size() / 2;
    vector<long long> left_a(a.begin(), a.begin() + mid);
    vector<long long> right_a(a.begin() + mid, a.end());
    vector<long long> left_sums = subset_sums(left_a);
    vector<long long> right_sum = subset_sums(right_a);
    sort(right_sum.begin(), right_sum.end());

    long long answer = 0;
    for (long long left_sum : left_sums) {
        auto [first, last] = equal_range(right_sum.begin(), right_sum.end(), target - left_sum);
        answer += static_cast<long long>(last - first);
    }
    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (long long& value : a) {
        cin >> value;
    }
    cout << count_subsets(a, target) << '\n';
}

